begin;do $$begin if current_setting('factorylean.disposable_test',true)is distinct from'true'or inet_server_addr()<>'127.0.0.1'::inet or inet_server_port()in(5432,55496)or current_database()<>'factory_lean_quality_local'then raise exception 'Explicit disposable test target required';end if;end$$;create schema prep_test;create table prep_test.checks(label text);create function prep_test.ok(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;insert into prep_test.checks values(label);end$$;create function prep_test.fails(statement text,code text)returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=code then insert into prep_test.checks values('Rejected '||code);return;end if;raise;end;raise exception 'Expected denial';end$$;
set local request.jwt.claim.sub='53d045ae-2bfe-4acb-8b98-e0e4b11dc81e';
do $$declare f uuid:='3ab24bb6-654e-40ab-a8bd-e0c8ca5c62c8';r jsonb;k uuid:=gen_random_uuid();raw uuid;compound uuid;product uuid;b uuid;foreign_factory uuid;warning_before jsonb;begin
warning_before:=public.planning_warning_policy_read(f);
perform prep_test.ok(public.production_material_configuration(f)->>'seconds'='21600','independent default six hours');r:=public.configure_production_materials(f,'WINDOW','{"hours":"1.5"}',k);perform prep_test.ok(r->>'seconds'='5400','exact1.5h');perform prep_test.ok(public.planning_warning_policy_read(f)=warning_before,'warning window unchanged');perform prep_test.ok(r=public.configure_production_materials(f,'WINDOW','{"hours":"1.5"}',k),'same UUID returns original');perform prep_test.ok((select count(*)=1 from private.production_material_config_events where request_id=k),'one audit on retry');perform prep_test.fails(format('select public.configure_production_materials(%L,%L,%L,%L)',f,'WINDOW','{"hours":"2"}',k),'40001');
perform prep_test.fails(format('select public.configure_production_materials(%L,%L,%L,%L)',f,'WINDOW','{"hours":"0"}',gen_random_uuid()),'22023');perform prep_test.fails(format('select public.configure_production_materials(%L,%L,%L,%L)',f,'WINDOW','{"hours":"NaN"}',gen_random_uuid()),'22023');perform prep_test.fails(format('select public.configure_production_materials(%L,%L,%L,%L)',f,'WINDOW','{"hours":"1.5","actor":"fake"}',gen_random_uuid()),'22023');
insert into public.materials(factory_id,name,code,unit)values(f,'QA recipe ingredient','PREP-RAW','kg')returning id into raw;
insert into public.products(factory_id,name,code,unit,stock_unit,product_kind,unit_weight_kg)values(f,'QA compound','PREP-COMPOUND','kg','kg','MANUFACTURED_INTERMEDIATE',1)returning id into compound;
insert into public.bom_versions(factory_id,product_id,version,batch_quantity,output_unit,created_by)values(f,compound,1,1,'kg',auth.uid())returning id into b;insert into public.bom_items(factory_id,bom_id,material_id,quantity,unit)values(f,b,raw,1,'kg');
insert into public.products(factory_id,name,code,unit,stock_unit,unit_weight_kg,formula_product_id)values(f,'QA pipe','PREP-PIPE','meter','meter',.5,compound)returning id into product;
r:=public.configure_production_materials(f,'ROUTE',jsonb_build_object('product',product,'mode','COMPOUND_STOCK'),gen_random_uuid());perform prep_test.ok(r->>'mode'='COMPOUND_STOCK','compound-only choice');r:=public.configure_production_materials(f,'ROUTE',jsonb_build_object('product',product,'mode','DIRECT_RAW'),gen_random_uuid());perform prep_test.ok(r->>'mode'='DIRECT_RAW','direct raw choice');perform prep_test.ok((select count(*)=1 from private.production_input_routes where product_id=product),'single exclusive route per stage');perform prep_test.ok((r->>'revision')::int=2,'route revision increments');r:=public.configure_production_materials(f,'ROUTE',jsonb_build_object('product',compound,'mode','COMPOUND_MANUFACTURE'),gen_random_uuid());perform prep_test.ok(r->>'mode'='COMPOUND_MANUFACTURE','own recipe compound manufacture');perform prep_test.fails(format('select public.configure_production_materials(%L,%L,%L,%L)',f,'ROUTE',jsonb_build_object('product',product,'mode','COMPOUND_MANUFACTURE'),gen_random_uuid()),'22023');perform prep_test.fails(format('select public.configure_production_materials(%L,%L,%L,%L)',f,'ROUTE',jsonb_build_object('product',product,'mode','BOTH'),gen_random_uuid()),'22023');
perform prep_test.fails('update private.production_material_config_events set operation=''FORGED''','42501');perform prep_test.ok(not has_table_privilege('authenticated','private.production_input_routes','INSERT'),'no client direct grants');perform prep_test.ok(not has_function_privilege('anon','public.configure_production_materials(uuid,text,jsonb,uuid)','EXECUTE'),'anonymous execute denied');
select id into foreign_factory from public.factories where id<>f limit 1;perform prep_test.fails(format('select public.production_material_configuration(%L)',foreign_factory),'42501');perform set_config('request.jwt.claim.sub','24511dcc-4e59-4973-881a-b9c02ffe535e',true);perform prep_test.fails(format('select public.configure_production_materials(%L,%L,%L,%L)',f,'WINDOW','{"hours":"2"}',gen_random_uuid()),'42501');end$$;select jsonb_build_object('count',count(*),'assertions',jsonb_agg(label))from prep_test.checks;rollback;